// ── Token / Adherence Dashboard ────────────────────────────────────────────
async function loadTokenDashboard() {
  const tokens = await API.get('/api/tokens/my') || [];
  const panel = document.getElementById('token-panel');
  if (!tokens.length) {
    panel.innerHTML = '<div class="text-muted text-center py-2 small">No prescription tokens issued yet.</div>';
    return;
  }

  const statusBadge = s => ({
    pending:  '<span class="badge bg-warning text-dark">Pending</span>',
    redeemed: '<span class="badge bg-success">Redeemed</span>',
    expired:  '<span class="badge bg-secondary">Expired</span>',
    cancelled:'<span class="badge bg-danger">Cancelled</span>',
  }[s] || `<span class="badge bg-light text-dark">${s}</span>`);

  const methodLabel = m => ({
    patient_pickup: '<i class="fa-solid fa-person-walking me-1"></i>Patient Pickup',
    asha_pickup:    '<i class="fa-solid fa-hands-holding me-1"></i>ASHA Pickup',
    home_delivery:  '<i class="fa-solid fa-truck-medical me-1"></i>Home Delivery',
  }[m] || m || '—');

  panel.innerHTML = tokens.map(t => `
    <div class="d-flex align-items-center gap-2 py-2 border-bottom" style="font-size:.82rem">
      <div style="flex:1;min-width:0">
        <div class="fw-semibold text-truncate">${t.patient_name || '—'}</div>
        <div class="text-muted" style="font-size:.73rem"><code>${t.token_id ? t.token_id.slice(0,16)+'…' : '—'}</code></div>
      </div>
      <div style="flex:0 0 auto">${statusBadge(t.redemption_status)}</div>
      <div class="text-muted" style="flex:0 0 auto;font-size:.75rem">
        ${t.redemption_status === 'redeemed'
          ? methodLabel(t.redemption_method) + '<br>' + (t.redeemed_at ? new Date(t.redeemed_at).toLocaleDateString('en-IN') : '')
          : (t.outlet_name || '—')}
      </div>
      ${t.adherence_block_index != null
        ? `<div class="text-success" style="flex:0 0 auto;font-size:.73rem"><i class="fa-solid fa-cube me-1"></i>Block #${t.adherence_block_index}</div>`
        : ''}
    </div>
  `).join('');
}

