async function loadPatientTokens(patientId) {
  const tokens = await API.get(`/api/tokens/patient/${patientId}`) || [];
  const el = document.getElementById('token-list');

  if (!tokens.length) {
    el.innerHTML = '<div class="text-muted text-center small">No tokens yet.</div>';
    return;
  }

  const statusBadge = s => ({
    pending:  '<span class="badge bg-warning text-dark">Pending Pickup</span>',
    redeemed: '<span class="badge bg-success">Redeemed</span>',
    expired:  '<span class="badge bg-secondary">Expired</span>',
    cancelled:'<span class="badge bg-danger">Cancelled</span>',
  }[s] || `<span class="badge bg-light text-dark">${s}</span>`);

  const methodIcon = m => ({
    patient_pickup: '<i class="fa-solid fa-person-walking me-1"></i>Patient Pickup',
    asha_pickup:    '<i class="fa-solid fa-hands-holding me-1"></i>ASHA Pickup',
    home_delivery:  '<i class="fa-solid fa-truck-medical me-1"></i>Home Delivery',
  }[m] || m || '—');

  el.innerHTML = tokens.map(t => `
    <div class="card mb-2 border-0" style="background:#f8fafc">
      <div class="card-body py-2 px-3">
        <div class="d-flex justify-content-between align-items-center mb-1">
          <code style="font-size:.73rem;color:#6b7280">${t.token_id ? t.token_id.slice(0,20)+'…' : '—'}</code>
          ${statusBadge(t.redemption_status)}
        </div>
        <div class="d-flex gap-3 small flex-wrap">
          <div><i class="fa-solid fa-store me-1 text-muted"></i>${t.outlet_name || '—'}</div>
          ${t.redemption_status === 'redeemed' ? `
            <div>${methodIcon(t.redemption_method)}</div>
            <div class="text-muted">${t.redeemed_at ? new Date(t.redeemed_at).toLocaleDateString('en-IN', {day:'numeric',month:'short',year:'numeric'}) : ''}</div>
          ` : `
            <div class="text-muted"><i class="fa-regular fa-calendar me-1"></i>
              Expires ${t.expires_at ? new Date(t.expires_at).toLocaleDateString('en-IN', {day:'numeric',month:'short',year:'numeric'}) : '—'}
            </div>
          `}
          ${t.adherence_block_index != null
            ? `<div class="text-success ms-auto"><i class="fa-solid fa-cube me-1"></i>Block #${t.adherence_block_index} verified</div>`
            : ''}
        </div>
      </div>
    </div>
  `).join('');
}

