// ── SOS Emergency System ──────────────────────────────────────────────────────

let sosGPSCoords = null;
let sosSelectedType = null;

// Capture GPS when SOS modal opens
document.getElementById('sosModal').addEventListener('show.bs.modal', function () {
  sosGPSCoords = null;
  sosSelectedType = null;
  document.getElementById('sos-type-value').value = '';
  document.getElementById('sos-notes').value = '';
  document.getElementById('sos-modal-result').innerHTML = '';
  document.getElementById('sos-submit-btn').disabled = false;
  document.querySelectorAll('.sos-type-btn').forEach(b => b.classList.remove('active', 'btn-danger', 'btn-warning', 'btn-secondary'));

  const gpsEl = document.getElementById('sos-gps-status');
  gpsEl.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-1"></i>Acquiring GPS...';

  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(
      pos => {
        sosGPSCoords = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
        gpsEl.innerHTML = '<i class="fa-solid fa-location-dot me-1 text-success"></i>GPS: ' +
          pos.coords.latitude.toFixed(4) + '°, ' + pos.coords.longitude.toFixed(4) + '°';
      },
      err => {
        gpsEl.innerHTML = '<i class="fa-solid fa-location-dot me-1 text-warning"></i>GPS unavailable — event will still be sent';
      },
      { timeout: 8000 }
    );
  }

  // Populate patient selector
  const sel = document.getElementById('sos-patient');
  const mainSel = document.getElementById('visit-patient');
  sel.innerHTML = '<option value="">— Select patient —</option>';
  Array.from(mainSel.options).forEach(o => {
    if (o.value) sel.appendChild(o.cloneNode(true));
  });
});

// Emergency type button selection
document.querySelectorAll('.sos-type-btn').forEach(btn => {
  btn.addEventListener('click', function () {
    document.querySelectorAll('.sos-type-btn').forEach(b => {
      b.classList.remove('active', 'btn-danger', 'btn-warning', 'btn-secondary');
      const t = b.dataset.type;
      const base = ['hypertensive_crisis','unconscious','breathing_difficulty','chest_pain'].includes(t)
        ? 'btn-outline-danger' : (t === 'other' ? 'btn-outline-secondary' : 'btn-outline-warning');
      b.className = b.className.replace(/btn-outline-\w+/g, base);
    });
    this.classList.add('active');
    if (['hypertensive_crisis','unconscious','breathing_difficulty','chest_pain'].includes(this.dataset.type)) {
      this.classList.replace('btn-outline-danger', 'btn-danger');
    } else if (this.dataset.type === 'other') {
      this.classList.replace('btn-outline-secondary', 'btn-secondary');
    } else {
      this.classList.replace('btn-outline-warning', 'btn-warning');
    }
    sosSelectedType = this.dataset.type;
    document.getElementById('sos-type-value').value = sosSelectedType;
  });
});

async function submitSOS() {
  const patientId = document.getElementById('sos-patient').value;
  const emergType = document.getElementById('sos-type-value').value;
  const notes     = document.getElementById('sos-notes').value;
  const resultEl  = document.getElementById('sos-modal-result');

  if (!patientId) { alert('Please select a patient.'); return; }
  if (!emergType) { alert('Please select the emergency type.'); return; }

  const btn = document.getElementById('sos-submit-btn');
  btn.disabled = true;
  btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-2"></i>Sending SOS...';

  const payload = {
    patient_id: parseInt(patientId),
    emergency_type: emergType,
    notes,
    client_timestamp: Date.now() / 1000,
    latitude:  sosGPSCoords ? sosGPSCoords.latitude  : null,
    longitude: sosGPSCoords ? sosGPSCoords.longitude : null,
  };

  const res = await API.post('/api/emergency', payload);

  if (res && res.event && res.event.event_id) {
    btn.innerHTML = '<i class="fa-solid fa-check me-2"></i>SOS Sent';
    resultEl.className = 'alert alert-success mt-2 py-2';
    resultEl.innerHTML = 'Emergency escalated. Triage instructions are now shown below.';

    // Close modal after short delay
    setTimeout(() => {
      const modal = bootstrap.Modal.getInstance(document.getElementById('sosModal'));
      if (modal) modal.hide();
    }, 1200);

    // Show triage panel
    showTriagePanel(res);
    loadEmergencies();
    // Update emergency stat counter
    document.getElementById('my-active-emergencies').textContent =
      parseInt(document.getElementById('my-active-emergencies').textContent || '0') + 1;
  } else {
    btn.disabled = false;
    btn.innerHTML = '<i class="fa-solid fa-bell-concierge me-2"></i>Send SOS Alert';
    resultEl.className = 'alert alert-danger mt-2 py-2';
    resultEl.innerHTML = (res && res.error) ? res.error : 'Failed to send SOS. Event saved offline.';

    // Offline fallback — queue locally
    try {
      const pending = JSON.parse(localStorage.getItem('sos_offline_queue') || '[]');
      pending.push({ ...payload, event_id: 'offline_' + Date.now(), queued_at: new Date().toISOString() });
      localStorage.setItem('sos_offline_queue', JSON.stringify(pending));
      resultEl.innerHTML += '<br><small><i class="fa-solid fa-clock me-1"></i>Saved offline — will sync when connectivity returns.</small>';
    } catch (e) {}
  }
}

function showTriagePanel(res) {
  const event    = res.event || {};
  const triage   = res.triage_instructions || [];
  const targets  = res.escalation_targets || {};
  const typeLabel = event.emergency_type_label || event.emergency_type || 'Emergency';

  document.getElementById('triage-type-label').textContent = typeLabel;
  document.getElementById('triage-steps').innerHTML = triage.map((step, i) =>
    '<div class="d-flex align-items-start gap-2 mb-2 p-2 rounded" style="background:#fff5f5">' +
    '<span class="badge bg-danger" style="min-width:24px">' + (i + 1) + '</span>' +
    '<span style="font-size:.9rem">' + step + '</span></div>'
  ).join('');

  const doc    = targets.doctor  || {};
  const phc    = targets.phc     || '—';
  const line   = targets.helpline || '—';
  document.getElementById('triage-escalation').innerHTML =
    '<strong><i class="fa-solid fa-phone-volume me-2"></i>Escalation Contacts:</strong><br>' +
    '<span class="me-3"><i class="fa-solid fa-user-doctor me-1"></i>' + (doc.name || 'Doctor') + ' — ' + (doc.phone || 'on file') + '</span>' +
    '<span class="me-3"><i class="fa-solid fa-hospital me-1"></i>' + phc + '</span>' +
    '<span><i class="fa-solid fa-phone-emergency me-1"></i>' + line + '</span>';

  if (res.block_index != null) {
    const badge = document.getElementById('triage-block-badge');
    badge.textContent = 'Blockchain Block #' + res.block_index + ' mined';
    badge.classList.remove('d-none');
  }

  document.getElementById('sos-triage-panel').classList.remove('d-none');
  document.getElementById('sos-triage-panel').scrollIntoView({ behavior: 'smooth' });
}

async function loadEmergencies() {
  const events = await API.get('/api/emergency') || [];
  const panel  = document.getElementById('emergency-history-panel');
  const activeCount = events.filter(e => e.status === 'active' || e.status === 'acknowledged').length;
  document.getElementById('my-active-emergencies').textContent = activeCount;

  if (!events.length) {
    panel.innerHTML = '<div class="text-muted text-center py-3 small">No emergency events on record.</div>';
    return;
  }

  const statusBadge = s => ({ active: '<span class="badge bg-danger">Active</span>',
    acknowledged: '<span class="badge bg-warning text-dark">Acknowledged</span>',
    resolved: '<span class="badge bg-success">Resolved</span>',
    escalated: '<span class="badge bg-danger">Escalated</span>' }[s] ||
    '<span class="badge bg-secondary">' + s + '</span>');

  const sevColor = s => s === 'CRITICAL' ? '#dc2626' : (s === 'HIGH' ? '#d97706' : '#6b7280');

  panel.innerHTML = events.map(e =>
    '<div class="d-flex align-items-center gap-2 px-3 py-2 border-bottom" style="font-size:.83rem">' +
    '<div style="width:6px;height:6px;border-radius:50%;background:' + sevColor(e.severity) + ';flex-shrink:0"></div>' +
    '<div style="flex:1;min-width:0">' +
    '<span class="fw-semibold">' + (e.patient_name || 'Patient') + '</span>' +
    '<span class="text-muted ms-2">' + (e.emergency_type || '').replace(/_/g,' ') + '</span>' +
    '</div>' +
    statusBadge(e.status) +
    '<small class="text-muted">' + new Date(e.created_at).toLocaleString('en-IN', {day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}) + '</small>' +
    (e.block_index != null ? '<small class="text-success"><i class="fa-solid fa-cube me-1"></i>Block #' + e.block_index + '</small>' : '') +
    '</div>'
  ).join('');

  // Try to sync offline queue
  const offline = JSON.parse(localStorage.getItem('sos_offline_queue') || '[]');
  if (offline.length) {
    API.post('/api/emergency/offline/sync', {}).then(() => {
      localStorage.removeItem('sos_offline_queue');
      loadEmergencies();
    }).catch(() => {});
  }
}

loadAsha();
loadEmergencies();
</script>
