// ── Emergency Panel (Doctor) ──────────────────────────────────────────────────
async function loadEmergencyPanel() {
  const events = await API.get('/api/emergency') || [];
  const panel  = document.getElementById('emergency-panel');
  const card   = document.getElementById('emergency-panel-card');
  const countEl = document.getElementById('emergency-count');

  countEl.textContent = events.length;
  card.style.display = events.length ? '' : 'none';

  if (!events.length) {
    panel.innerHTML = '<div class="text-muted text-center py-3 small">No active emergencies.</div>';
    return;
  }

  const sevColor = s => s === 'CRITICAL' ? '#dc2626' : (s === 'HIGH' ? '#d97706' : '#6b7280');
  const sevBg    = s => s === 'CRITICAL' ? '#fef2f2' : (s === 'HIGH' ? '#fff7ed' : '#f9fafb');

  const statusBadge = s => ({
    active:       '<span class="badge bg-danger">Active</span>',
    acknowledged: '<span class="badge bg-warning text-dark">Acknowledged</span>',
    escalated:    '<span class="badge bg-danger">Escalated</span>',
  }[s] || '<span class="badge bg-secondary">' + s + '</span>');

  panel.innerHTML = events.map(e =>
    '<div class="px-3 py-2 border-bottom d-flex align-items-start gap-3" style="background:' + sevBg(e.severity) + ';font-size:.84rem">' +
    '<div style="flex:0 0 auto;padding-top:3px">' +
    '<span class="fw-bold" style="color:' + sevColor(e.severity) + '">' + (e.severity || 'HIGH') + '</span>' +
    '</div>' +
    '<div style="flex:1;min-width:0">' +
    '<div class="fw-semibold">' + (e.patient_name || 'Patient') + ' <span class="text-muted fw-normal">· ' + (e.patient_village || '') + '</span></div>' +
    '<div class="text-muted">' + (e.emergency_type || '').replace(/_/g,' ') + ' · ASHA: ' + (e.asha_name || '—') + '</div>' +
    (e.latest_bp_systolic ? '<div class="small">BP: <strong>' + e.latest_bp_systolic + '/' + e.latest_bp_diastolic + '</strong> mmHg · Risk: ' + (e.latest_risk_level || '—') + '</div>' : '') +
    '</div>' +
    '<div class="d-flex flex-column align-items-end gap-1" style="flex:0 0 auto">' +
    statusBadge(e.status) +
    '<small class="text-muted">' + new Date(e.created_at).toLocaleTimeString('en-IN', {hour:'2-digit',minute:'2-digit'}) + '</small>' +
    (e.block_index != null ? '<small class="text-success"><i class="fa-solid fa-cube me-1"></i>#' + e.block_index + '</small>' : '') +
    (e.status === 'active'
      ? '<button class="btn btn-xs btn-outline-warning py-0 px-2" style="font-size:.75rem" onclick="acknowledgeEmergency(\'' + e.event_id + '\')">Acknowledge</button>'
      : '') +
    '</div>' +
    '</div>'
  ).join('');
}

async function acknowledgeEmergency(eventId) {
  const res = await API.post('/api/emergency/' + eventId + '/acknowledge', {});
  if (res && res.message) loadEmergencyPanel();
}

loadDoctor();
